function entryLabel(e){if(!e.transferId)return TYPES[e.kind];return e.transferRole==='out'?'⇄ Transfer → '+(party(e.toPartyId)?.name||e.toName||'Account'):'⇄ Transfer ← '+(party(e.fromPartyId)?.name||e.fromName||'Account')}
