function cashBookRows(book){const q=norm($('search').value);return [...book.rows].reverse().filter(r=>!q||norm(r.label+' '+custodyName(r.partyId)+' '+custodyName(r.from)+' '+custodyName(r.to)+' '+r.note).includes(q))}
